using System.Security.Cryptography;
using System.Text;
using CommerceErp.Core;
using static CommerceErp.Infrastructure.CommerceDatabase;
using static CommerceErp.Core.BusinessUnits;
namespace CommerceErp.Infrastructure;

public sealed class InventoryDocumentService(CommerceDatabase database,Action<string>? fault=null)
{
    private static string Actor=>SecurityContext.Current?.User.Id??"local-tool";
    private static void Text(string value,string name,int max=500)=>MasterDataService.Text(value,name,max);
    private static long Signed(decimal value){if(value < -1000000000||value>1000000000)throw new BusinessRuleException("数量超过上限。");if(value==0)throw new BusinessRuleException("调整数量不能为0。");return value<0?-Quantity(-value):Quantity(value);}
    private InventoryDocumentResult Command(string op,string kind,object input,string reason,Func<DbSession,InventoryDocumentResult> action)
    {
        if(!Guid.TryParse(op,out var id)||id==Guid.Empty)throw new BusinessRuleException("操作号须为非空GUID。");Text(reason,"原因");var hash=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(Json(input))));
        return database.Write(db=>{var old=db.Query("SELECT Kind,RequestHash,ResponseJson FROM Operations WHERE TenantId=$t AND OperationId=$op",r=>(Kind:r.GetString(0),Hash:r.GetString(1),Json:r.GetString(2)),("t",Tenant(db)),("op",op)).SingleOrDefault();if(old.Json is not null){if(old.Kind!=kind||old.Hash!=hash)throw new ConflictException("操作号已用于其他请求。");return FromJson<InventoryDocumentResult>(old.Json) with{Replayed=true};}var result=action(db);db.Execute("INSERT INTO Operations VALUES($t,$op,$kind,$hash,$json,$now)",("t",Tenant(db)),("op",op),("kind",kind),("hash",hash),("json",Json(result)),("now",Now()));fault?.Invoke("before-commit");return result;});
    }
    private static void History(DbSession db,string id,string action,string reason,object data)=>db.Execute("INSERT INTO InventoryDocumentHistory VALUES($id,$doc,$action,$actor,$reason,$now,$json)",("id",Guid.NewGuid().ToString("N")),("doc",id),("action",action),("actor",Actor),("reason",reason),("now",Now()),("json",Json(data)));
    private const string Columns="Id,Number,Kind,State,Version,CreatedBy,ApprovedBy,Reason,Evidence,CreatedAt,ReversalOf,LinesJson";
    private static InventoryDocument Read(DbRow r)=>new(r.GetString(0),r.GetString(1),Enum.Parse<InventoryDocumentKind>(r.GetString(2)),r.GetString(3),r.GetInt64(4),r.GetString(5),r.GetString(6),r.GetString(7),r.GetString(8),r.GetString(9),r.IsDBNull(10)?null:r.GetString(10),FromJson<List<InventoryPreparedLine>>(r.GetString(11)));
    private static InventoryDocument Get(DbSession db,string id)=>db.Query("SELECT "+Columns+" FROM InventoryDocuments WHERE Id=$id",Read,("id",id)).SingleOrDefault()??throw new BusinessRuleException("库存单据不存在。");
    private static InventoryDocumentBalance Balance(DbSession db,string id)=>db.Query("SELECT b.SkuId,s.Code,s.Name,b.OnHandUnits,b.ReservedUnits,b.FrozenUnits,b.SafetyUnits,b.Version,q.QuantityUnits,q.Version,ms.Version FROM InventoryBalances b JOIN Skus s ON s.Id=b.SkuId AND s.TenantId=b.TenantId JOIN MasterSkuData ms ON ms.SkuId=s.Id JOIN QuarantineBalances q ON q.TenantId=b.TenantId AND q.OwnerId=b.OwnerId AND q.WarehouseId=b.WarehouseId AND q.SkuId=b.SkuId WHERE b.TenantId=$t AND b.SkuId=$id AND s.ComponentsJson='[]'",r=>new InventoryDocumentBalance(r.GetString(0),r.GetString(1),r.GetString(2),FromQuantity(r.GetInt64(3)),FromQuantity(r.GetInt64(4)),FromQuantity(r.GetInt64(5)),FromQuantity(r.GetInt64(6)),r.GetInt64(7),FromQuantity(r.GetInt64(8)),r.GetInt64(9),r.GetInt64(10)),("t",Tenant(db)),("id",id)).SingleOrDefault()??throw new BusinessRuleException("请选择当前仓库的普通商品。");
    public InventoryDocumentBalance GetBalanceByCode(string code)=>database.Read(db=>Balance(db,db.Scalar<string>("SELECT Id FROM Skus WHERE TenantId=$t AND Code=$code",("t",Tenant(db)),("code",code))??throw new BusinessRuleException("SKU编码不存在。")));
    public InventoryDocumentBalance GetBalance(string sku)=>database.Read(db=>Balance(db,sku));
    private static void Validate(InventoryDocumentBalance b,InventoryPreparedLine line)
    {if(b.SkuVersion!=line.SkuVersion||b.Version!=line.InventoryVersion||b.QuarantineVersion!=line.QuarantineVersion)throw new ConflictException("库存或隔离版本已变化，请重新核对并修改草稿。");var hand=b.OnHand+line.OnHandDelta;var quarantine=b.Quarantined+line.QuarantineDelta;if(hand<0||quarantine<0||hand>1000000000||quarantine>1000000000||hand<b.Reserved+b.Frozen)throw new BusinessRuleException("库存不足或超过上限，不能减少已经预占或冻结的数量；请先核查原业务。");}
    private static List<InventoryPreparedLine> Prepare(DbSession db,InventoryDocumentKind kind,List<InventoryDocumentLine> lines)
    {
        if(!Enum.IsDefined(kind)||kind==InventoryDocumentKind.Reversal)throw new BusinessRuleException("单据类型无效，冲销须从已审核单发起。");if(lines is null||lines.Count is <1 or >200||lines.Any(l=>l is null)||lines.Select(l=>l.SkuId).Distinct().Count()!=lines.Count)throw new BusinessRuleException("明细须为1–200个不重复商品。");var result=new List<InventoryPreparedLine>();
        foreach(var line in lines){var b=Balance(db,line.SkuId);if(line.ExpectedInventoryVersion!=b.Version||line.ExpectedQuarantineVersion!=b.QuarantineVersion||line.ExpectedSkuVersion!=b.SkuVersion)throw new ConflictException("账面版本变化，请重新核对。");decimal hand=0,q=0;
            switch(kind){case InventoryDocumentKind.Adjustment:hand=FromQuantity(Signed(line.Value));if(line.QuarantineCount!=0)throw new BusinessRuleException("调整单仅调整良品在库，隔离差异请用盘点。");break;
            case InventoryDocumentKind.Count:Quantity(line.Value);Quantity(line.QuarantineCount);hand=line.Value-b.OnHand;q=line.QuarantineCount-b.Quarantined;break;
            default:if(line.Value<=0||line.QuarantineCount!=0)throw new BusinessRuleException("隔离处置数量须大于0。");Quantity(line.Value);q=-line.Value;if(kind==InventoryDocumentKind.QuarantineRelease){if(db.Scalar<int>("SELECT Enabled FROM Skus WHERE Id=$id",("id",line.SkuId))!=1)throw new BusinessRuleException("停用商品不能转为可用良品。");hand=line.Value;}break;}
            var prepared=new InventoryPreparedLine(b.SkuId,b.OnHand,b.Quarantined,hand,q,b.Version,b.QuarantineVersion,b.SkuVersion);Validate(b,prepared);result.Add(prepared);
        }return result;
    }
    private static InventoryDocumentResult Insert(DbSession db,string number,InventoryDocumentKind kind,List<InventoryPreparedLine> lines,string reason,string evidence,string? reversal=null)
    {Text(number,"单号",100);Text(evidence,"依据/实物凭证",1000);if(db.Scalar<int>("SELECT COUNT(*) FROM InventoryDocuments WHERE Number=$n",("n",number))!=0)throw new ConflictException("单号已存在。");var id=Guid.NewGuid().ToString("N");db.Execute("INSERT INTO InventoryDocuments VALUES($id,$n,$kind,'Draft',1,$actor,'',$reason,$evidence,$now,$reverse,$lines)",("id",id),("n",number),("kind",kind.ToString()),("actor",Actor),("reason",reason),("evidence",evidence),("now",Now()),("reverse",reversal),("lines",Json(lines)));History(db,id,"Create",reason,new{kind,lines,evidence,reversal});return new(id,1,false,"草稿已保存，尚未改动库存。");}
    public InventoryDocumentResult Create(InventoryDocumentRequest r)=>Command(r.OperationId,"InventoryDocCreate",r,r.Reason,db=>Insert(db,r.Number,r.Kind,Prepare(db,r.Kind,r.Lines),r.Reason,r.Evidence));
    private static void Draft(InventoryDocument doc,long version){if(doc.State!="Draft"||doc.Version!=version)throw new ConflictException("仅能操作版本一致的草稿。");}
    public InventoryDocumentResult Edit(string id,EditInventoryDocumentRequest r)=>Command(r.OperationId,"InventoryDocEdit",new{id,r},r.Reason,db=>{var doc=Get(db,id);Draft(doc,r.ExpectedVersion);if(doc.Kind==InventoryDocumentKind.Reversal)throw new BusinessRuleException("冲销明细由原单生成，不可编辑；请作废后重新发起。");Text(r.Evidence,"依据/实物凭证",1000);var lines=Prepare(db,doc.Kind,r.Lines);db.Execute("UPDATE InventoryDocuments SET LinesJson=$lines,Reason=$reason,Evidence=$e,Version=Version+1 WHERE Id=$id",("lines",Json(lines)),("reason",r.Reason),("e",r.Evidence),("id",id));History(db,id,"Edit",r.Reason,new{Before=doc,After=lines});return new(id,doc.Version+1,false,"草稿已修改，未改变库存。");});
    public InventoryDocumentResult Void(string id,InventoryDocumentAction r)=>Command(r.OperationId,"InventoryDocVoid",new{id,r},r.Reason,db=>{var doc=Get(db,id);Draft(doc,r.ExpectedVersion);db.Execute("UPDATE InventoryDocuments SET State='Voided',Version=Version+1 WHERE Id=$id",("id",id));History(db,id,"Void",r.Reason,doc);return new(id,doc.Version+1,false,"草稿已作废。");});
    private static List<InventoryMovement> Movements(DbSession db,string id)=>db.Query("SELECT DocumentId,SkuId,OnHandDelta,QuarantineDelta,OnHandAfter,QuarantineAfter,InventoryVersion,QuarantineVersion FROM InventoryMovements WHERE DocumentId=$id ORDER BY SkuId",r=>new InventoryMovement(r.GetString(0),r.GetString(1),FromQuantity(r.GetInt64(2)),FromQuantity(r.GetInt64(3)),FromQuantity(r.GetInt64(4)),FromQuantity(r.GetInt64(5)),r.GetInt64(6),r.GetInt64(7)),("id",id));
    public InventoryDocumentResult Reverse(string id,ReverseInventoryDocumentRequest r)=>Command(r.OperationId,"InventoryDocReverse",new{id,r},r.Reason,db=>{var doc=Get(db,id);if(doc.State!="Approved"||doc.Version!=r.ExpectedVersion||doc.Kind==InventoryDocumentKind.Reversal)throw new ConflictException("只能冲销版本一致、未被冲销的原审核单。");var lines=Movements(db,id).Select(m=>{var b=Balance(db,m.SkuId);var line=new InventoryPreparedLine(m.SkuId,b.OnHand,b.Quarantined,-m.OnHandDelta,-m.QuarantineDelta,b.Version,b.QuarantineVersion,b.SkuVersion);Validate(b,line);return line;}).ToList();return Insert(db,r.Number,InventoryDocumentKind.Reversal,lines,r.Reason,r.Evidence,id);});
    public InventoryDocumentResult Approve(string id,InventoryDocumentAction r)=>Command(r.OperationId,"InventoryDocApprove",new{id,r},r.Reason,db=>
    {
        var doc=Get(db,id);Draft(doc,r.ExpectedVersion);if(SecurityContext.Current is not null&&(doc.CreatedBy==Actor||db.Scalar<int>("SELECT COUNT(*) FROM InventoryDocumentHistory WHERE DocumentId=$id AND Action='Edit' AND ActorId=$actor",("id",id),("actor",Actor))>0))throw new BusinessRuleException("制单人及修改人不能审核本单，请另一审核账号操作。");
        if(doc.ReversalOf is{} original){var source=Get(db,original);if(source.State!="Approved"||source.Kind==InventoryDocumentKind.Reversal||db.Scalar<int>("SELECT COUNT(*) FROM InventoryReversals WHERE OriginalId=$id",("id",original))>0)throw new ConflictException("原单已被冲销。");db.Execute("INSERT INTO InventoryReversals VALUES($source,$id)",("source",original),("id",id));}
        foreach(var line in doc.Lines){var before=Balance(db,line.SkuId);Validate(before,line);if(doc.Kind==InventoryDocumentKind.QuarantineRelease&&db.Scalar<int>("SELECT Enabled FROM Skus WHERE Id=$id",("id",line.SkuId))!=1)throw new BusinessRuleException("商品已停用，请重新核查。");var hand=SignedOrZero(line.OnHandDelta);var q=SignedOrZero(line.QuarantineDelta);
            if(hand!=0)db.Execute("UPDATE InventoryBalances SET OnHandUnits=OnHandUnits+$q,Version=Version+1 WHERE TenantId=$t AND SkuId=$s",("q",hand),("t",Tenant(db)),("s",line.SkuId));
            if(q!=0)db.Execute("UPDATE QuarantineBalances SET QuantityUnits=QuantityUnits+$q,Version=Version+1 WHERE TenantId=$t AND SkuId=$s",("q",q),("t",Tenant(db)),("s",line.SkuId));
            var after=Balance(db,line.SkuId);db.Execute("INSERT INTO InventoryMovements VALUES($doc,$sku,$h,$q,$ha,$qa,$v,$qv)",("doc",id),("sku",line.SkuId),("h",hand),("q",q),("ha",Quantity(after.OnHand)),("qa",Quantity(after.Quarantined)),("v",after.Version),("qv",after.QuarantineVersion));
            if(hand!=0){db.Execute("INSERT INTO InventoryLedger(TenantId,OwnerId,WarehouseId,SkuId,OperationId,Action,OnHandDelta,ReservedDelta,OnHandAfter,ReservedAfter,FrozenAfter,SafetyAfter,Reason,CreatedAt,StockDocumentId) SELECT TenantId,OwnerId,WarehouseId,SkuId,$op,$action,$h,0,OnHandUnits,ReservedUnits,FrozenUnits,SafetyUnits,$reason,$now,$doc FROM InventoryBalances WHERE TenantId=$t AND SkuId=$s",("op",r.OperationId),("action",doc.Kind.ToString()),("doc",id),("h",hand),("reason",$"库存单 {id}：{r.Reason}"),("now",Now()),("t",Tenant(db)),("s",line.SkuId));db.Execute("INSERT INTO Outbox(Id,TenantId,AggregateId,AggregateVersion,EventType,PayloadJson,CreatedAt,UpdatedAt,NextAttemptAt) VALUES($id,$t,$agg,$v,'StockAdjusted',$json,$now,$now,$now)",("id",Guid.NewGuid().ToString("N")),("t",Tenant(db)),("agg","stock:"+line.SkuId),("v",after.Version),("json",Json(new{documentId=id,skuId=line.SkuId,onHand=after.OnHand,delta=line.OnHandDelta})),("now",Now()));}
            fault?.Invoke("after-line");
        }
        db.Execute("UPDATE InventoryDocuments SET State='Approved',ApprovedBy=$actor,Version=Version+1 WHERE Id=$id",("actor",Actor),("id",id));if(doc.ReversalOf is{} originalId){db.Execute("UPDATE InventoryDocuments SET State='Reversed',Version=Version+1 WHERE Id=$id",("id",originalId));History(db,originalId,"Reversed",r.Reason,new{reversalId=id});}History(db,id,"Approve",r.Reason,new{doc.Lines,doc.Evidence});return new(id,doc.Version+1,false,"审核入账完成，余额、流水与事件已同事务保存。");
    });
    private static long SignedOrZero(decimal value)=>value==0?0:Signed(value);
    public InventoryDocumentDetails Details(string id)=>database.Read(db=>new InventoryDocumentDetails(Get(db,id),Movements(db,id),db.Query("SELECT Action,ActorId,Reason,CreatedAt,DataJson FROM InventoryDocumentHistory WHERE DocumentId=$id ORDER BY CreatedAt,Id",r=>new InventoryDocumentHistory(r.GetString(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4)),("id",id))));
    public MasterPage<InventoryDocument> List(int page=1,int size=50,string search="",string state="")=>database.Read(db=>{if(page<1||page>100000||size<1||size>200||search.Length>100||!new[]{"","Draft","Approved","Voided","Reversed"}.Contains(state))throw new BusinessRuleException("查询条件无效。");var where=" FROM InventoryDocuments WHERE (CHARINDEX($q,Number)>0) AND ($state='' OR State=$state)";var args=new (string,object?)[]{("q",search),("state",state),("offset",(page-1)*size),("limit",size)};return new MasterPage<InventoryDocument>(db.Query("SELECT "+Columns+where+" ORDER BY CreatedAt DESC,Id DESC"+db.Page,Read,args),db.Scalar<int>("SELECT COUNT(*)"+where,args),page,size);});
    public InventoryDocumentAudit Audit()=>database.Read(db=>{var problems=new List<string>();var docs=db.Query("SELECT "+Columns+" FROM InventoryDocuments ORDER BY Id",Read);foreach(var doc in docs){var moves=Movements(db,doc.Id);if(doc.State is "Draft" or "Voided"){if(moves.Count!=0)problems.Add(doc.Number+"：未入账单存在流水");continue;}if(moves.Count!=doc.Lines.Count)problems.Add(doc.Number+"：明细与流水数量不同");foreach(var line in doc.Lines){var m=moves.SingleOrDefault(x=>x.SkuId==line.SkuId);if(m is null||m.OnHandDelta!=line.OnHandDelta||m.QuarantineDelta!=line.QuarantineDelta||m.OnHandAfter!=line.OnHandBefore+line.OnHandDelta||m.QuarantineAfter!=line.QuarantineBefore+line.QuarantineDelta)problems.Add(doc.Number+"：明细流水不符");var sum=db.Scalar<long>("SELECT COALESCE(SUM(OnHandDelta),0) FROM InventoryLedger WHERE StockDocumentId=$id AND SkuId=$sku",("id",doc.Id),("sku",line.SkuId));if(sum!=SignedOrZero(line.OnHandDelta))problems.Add(doc.Number+"：主库流水不符");}if(doc.ReversalOf is{} original&&db.Scalar<int>("SELECT COUNT(*) FROM InventoryReversals WHERE OriginalId=$o AND ReversalId=$id",("o",original),("id",doc.Id))!=1)problems.Add(doc.Number+"：冲销关联缺失");}return new InventoryDocumentAudit(problems.Count==0,docs.Count,problems);});

}
